import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> tokens = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            StringTokenizer st = new StringTokenizer(line);
            while (st.hasMoreTokens()) tokens.add(st.nextToken());
        }
        String pattern = tokens.get(0);
        // One allowed-character set per pattern unit.
        List<boolean[]> slots = new ArrayList<>();
        for (int i = 0; i < pattern.length();) {
            boolean[] allowed = new boolean[65536];
            if (pattern.charAt(i) == '[') {
                int j = pattern.indexOf(']', i);
                for (int k = i + 1; k < j; k++) allowed[pattern.charAt(k)] = true;
                i = j + 1;
            } else {
                allowed[pattern.charAt(i)] = true;
                i++;
            }
            slots.add(allowed);
        }
        List<String> matches = new ArrayList<>();
        for (int t = 2; t < tokens.size(); t++) {
            String w = tokens.get(t);
            if (w.length() != slots.size()) continue;
            boolean ok = true;
            for (int i = 0; i < w.length() && ok; i++) ok = slots.get(i)[w.charAt(i)];
            if (ok) matches.add(w);
        }
        StringBuilder sb = new StringBuilder().append(matches.size());
        for (String m : matches) sb.append(' ').append(m);
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
	"strings"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	var tokens []string
	for sc.Scan() {
		tokens = append(tokens, sc.Text())
	}
	pattern := tokens[0]
	// One allowed-character set per pattern unit.
	var slots [][256]bool
	for i := 0; i < len(pattern); {
		var allowed [256]bool
		if pattern[i] == '[' {
			j := i + strings.IndexByte(pattern[i:], ']')
			for k := i + 1; k < j; k++ {
				allowed[pattern[k]] = true
			}
			i = j + 1
		} else {
			allowed[pattern[i]] = true
			i++
		}
		slots = append(slots, allowed)
	}
	var matches []string
	for _, w := range tokens[2:] {
		if len(w) != len(slots) {
			continue
		}
		ok := true
		for i := 0; i < len(w) && ok; i++ {
			ok = slots[i][w[i]]
		}
		if ok {
			matches = append(matches, w)
		}
	}
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	out.WriteString(strconv.Itoa(len(matches)))
	for _, m := range matches {
		out.WriteString(" " + m)
	}
	out.WriteString("\n")
}
